import React,{useState as S} from 'https://esm.sh/react@19.1.0';
import{createRoot}from'https://esm.sh/react-dom@19.1.0/client';
import htm from'https://esm.sh/htm@3.1.1';
const html=htm.bind(React.createElement);
const photo=(id,w=1100)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=85`;
const images=[photo('photo-1539008835657-9e8e9680c956'),photo('photo-1595777457583-95e059d581b8'),photo('photo-1534528741775-53994a69daeb'),photo('photo-1483985988355-763728e1935b')];
const products=[{id:1,name:['Sản Phẩm Hương Vân Sa Cao Cấp','An Nhien Dress'],type:'dress',label:['ĐẦM DÁNG DÀI','LONG DRESS'],image:images[0],color:'#958668'},{id:2,name:['Sản Phẩm Jinzhaocheng','Moc Mien Dress'],type:'dress',label:['ĐẦM THANH LỊCH','ELEGANT DRESS'],image:images[1],color:'#522f2e'},{id:3,name:['Sản Phẩm Tourou','Thanh Van Top'],type:'top',label:['ÁO & PHỐI LỚP','TOPS & LAYERS'],image:images[2],color:'#33352c'},{id:4,name:['Các Sản Phẩm Lụa Tơ Cao Cấp Khác','Tinh Lang Set'],type:'set',label:['BỘ PHỐI ĐỒ','COORDINATED SET'],image:images[3],color:'#b4a38b'}];
function Contact({lang}){const t=(a,b)=>lang?b:a;return html`<div className="contactdetails"><p>103 Giang Văn Minh, Đội Cấn, Ba Đình, Hà Nội</p><p>${t('Điện thoại / Zalo','Phone / Zalo')}: <a href="tel:+84912067155">0912 067 155</a></p><div className="contactbuttons"><a className="solid" href="https://zalo.me/84912067155" target="_blank" rel="noopener noreferrer">${t('TƯ VẤN QUA ZALO','CHAT ON ZALO')} ↗</a><a className="textlink" href="tel:+84912067155">${t('GỌI CHO SHOP','CALL THE SHOP')} ↗</a></div><p className="meta"><a className="textlink" href="https://facebook.com/mesa.tere" target="_blank" rel="noopener noreferrer">${t('TƯ VẤN QUA FACEBOOK','CONTACT ON FACEBOOK')} ↗</a></p></div>`}
function Policies({lang}){const t=(a,b)=>lang?b:a;return html`<div className="policygrid"><div><span className="eyebrow">01 / ${t('ĐẶT HÀNG','ORDERING')}</span><h3>${t('Chọn đúng kích cỡ','Find the right size')}</h3><p>${t('Xác nhận chiều cao, cân nặng và kích cỡ trước khi đặt hàng. Liên hệ shop qua Zalo hoặc điện thoại để được tư vấn.','Confirm your height, weight and size before ordering. Contact the shop on Zalo or by phone for advice.')}</p></div><div><span className="eyebrow">02 / ${t('ĐỔI HÀNG','EXCHANGES')}</span><h3>${t('Hỗ trợ đổi một lần','One exchange')}</h3><p>${t('Khách mua tại cửa hàng được hỗ trợ đổi một lần trong ngày. Shop không hoàn lại tiền.','In-store purchases may be exchanged once on the same day. The shop does not offer refunds.')}</p></div><div><span className="eyebrow">03 / ${t('PHÍ VẬN CHUYỂN','SHIPPING FEES')}</span><h3>${t('Giao hàng toàn Việt Nam','Delivery across Vietnam')}</h3><p>${t('Khách ở xa: giá đơn hàng + 30.000 VNĐ phí ship. Phí ship nếu hoàn hàng: 50.000 VNĐ.','Remote orders: order value + 30,000 VND shipping. Shipping fee if goods are returned: 50,000 VND.')}</p><p className="meta">${t('Phí hoàn hàng không đồng nghĩa với chính sách hoàn tiền. Phương thức thanh toán và thời gian giao: chờ shop xác nhận.','Return shipping does not imply a refund policy. Payment methods and delivery timing: awaiting shop confirmation.')}</p></div></div>`}
function App(){const[lang,L]=S(0),[page,P]=S(null),[filter,F]=S('all'),[panel,Q]=S(null),[size,Z]=S('M'),[query,U]=S(''),[added,A]=S(false),[cart,C]=S(()=>{try{return JSON.parse(localStorage.getItem('tb-cart')||'[]')}catch{return[]}});const t=(a,b)=>lang?b:a;function save(v){C(v);localStorage.setItem('tb-cart',JSON.stringify(v))}function open(p){P(p);Z('M');A(false);Q(null);window.scrollTo(0,0)}function home(anchor){P(null);Q(null);setTimeout(()=>document.getElementById(anchor)?.scrollIntoView(),30)}function add(){save([...cart,{id:page.id,size,key:Date.now()}]);A(true)}const card=p=>html`<button className="product" key=${p.id} onClick=${()=>open(p)}><div className="productphoto"><img src=${p.image} alt=${t('Ảnh phong cách minh họa, không phải sản phẩm thực tế','Style illustration, not an actual product')} loading="lazy"/><span className="tag">${p.label[lang]}</span></div><h3>${p.name[lang]}</h3><div className="meta">${t('Mẫu ý tưởng · Ảnh minh họa','Concept style · Illustrative image')}</div><div className="productbottom"><span><i className="swatch" style=${{background:p.color}}></i>${t('Bảng màu gợi ý','Suggested palette')}</span><span>${t('Giá VNĐ: chờ cập nhật','Price to be confirmed')} ↗</span></div></button>`;
return html`<div><div className="announcement">${t('TRUNG BÉO LUXURY — PHONG CÁCH LỤA, DẤU ẤN RIÊNG','TRUNG BÉO LUXURY — SILK STYLE, YOUR OWN SIGNATURE')}</div><header><div className="nav"><button className="mobilemenu" aria-label="Menu" onClick=${()=>Q('menu')}>☰</button><a href="#" className="wordmark" onClick=${e=>{e.preventDefault();open(null)}}><img className="brandpic" src="assets/brand.jpg" alt="Logo Trung Béo Luxury"/><span className="brandtext">Trung Béo<small>LUXURY</small></span></a><nav><a href="#collection" onClick=${e=>{e.preventDefault();home('collection')}}>${t('Bộ sưu tập','Collection')}</a><a href="#story" onClick=${e=>{e.preventDefault();home('story')}}>${t('Hương Vân Sa','Huong Van Sa')}</a><a href="#style" onClick=${e=>{e.preventDefault();home('style')}}>${t('Cảm hứng','Inspiration')}</a><a href="#contact" onClick=${e=>{e.preventDefault();home('contact')}}>${t('Liên hệ','Contact')}</a></nav><div className="actions"><button onClick=${()=>L(1-lang)} aria-label="Switch language">${lang?'EN / VN':'VN / EN'}</button><button className="searchbtn" onClick=${()=>Q('search')}>${t('Tìm kiếm','Search')} ⌕</button><button onClick=${()=>Q('cart')}>${t('Yêu thích','Saved')} (${cart.length})</button></div></div></header>
${page?html`<main className="detail"><div className="breadcrumbs"><button onClick=${()=>open(null)}>${t('Trang chủ','Home')}</button> / <button onClick=${()=>home('collection')}>${t('Bộ sưu tập','Collection')}</button> / ${page.name[lang]}</div><div className="detailgrid"><div className="detailphotos"><img src=${page.image} alt=${t('Ảnh minh họa phong cách','Illustrative style image')}/><img src="assets/brand.jpg" alt="Trung Béo Luxury — nhận diện thương hiệu"/></div><div className="detailinfo"><span className="eyebrow">TRUNG BÉO LUXURY / ${page.label[lang]}</span><h1>${page.name[lang]}</h1><p>${t('Mẫu ý tưởng để khám phá phong cách. Hình ảnh chưa đại diện cho sản phẩm đang bán.','A concept for exploring your style. Images do not represent an available product.')}</p><p>${t('Giá: chờ xác nhận','Price: to be confirmed')}</p><div className="notice">${t('Thông tin thành phần, xuất xứ, số đo và tồn kho chưa được cung cấp. Chưa xác nhận mẫu này sử dụng lụa Hương Vân Sa.','Composition, origin, measurements and stock are not yet provided. Huong Van Sa silk is not verified for this style.')}</div><span className="eyebrow">${t('Chọn cỡ tham khảo','Select a reference size')}</span><div className="sizes">${['S','M','L','XL'].map(s=>html`<button className=${size===s?'selected':''} onClick=${()=>Z(s)} aria-pressed=${size===s}>${s}</button>`)}</div><button className="solid full" onClick=${add}>${t('LƯU MẪU YÊU THÍCH','SAVE THIS STYLE')} <span>↗</span></button>${added&&html`<div className="success" role="status">${t('Đã thêm vào túi đồ mẫu.','Added to your sample bag.')} <button onClick=${()=>Q('cart')}>${t('Xem túi đồ →','View bag →')}</button></div>`}<details open><summary>${t('Thông tin sản phẩm','Product information')}</summary><p>${t('Tên mẫu và bảng màu là nội dung đề xuất cho thiết kế website. Sẽ cập nhật ảnh thật và hồ sơ sản phẩm trước khi mở bán.','Style names and palettes are website design proposals. Actual images and product documentation will be added before sales open.')}</p></details><details><summary>${t('Kích cỡ & phom dáng','Size & fit')}</summary><p>${t('S/M/L/XL hiện chỉ là lựa chọn minh họa. Bảng số đo cần được xác nhận theo từng mẫu.','S/M/L/XL are illustrative options. Measurements must be confirmed for each style.')}</p></details><details><summary>${t('Giao hàng & đổi trả','Delivery & returns')}</summary><p>${t('Phục vụ Hà Nội và toàn Việt Nam. Khách ở xa: phí ship 30.000 VNĐ cộng giá đơn hàng; phí ship nếu hoàn hàng 50.000 VNĐ. Khách mua tại cửa hàng: đổi một lần trong ngày. Shop không hoàn tiền. Xem quy định đầy đủ trên trang chủ.','Delivery across Vietnam. Remote orders: shipping 30,000 VND plus order value; return shipping 50,000 VND. In-store purchases: one exchange on the same day. No refunds. See the full policy on the home page.')}</p></details></div></div></main>`:html`<main><section className="hero"><div className="herocopy"><span className="eyebrow">THE SILK EDIT / TRUNG BÉO LUXURY</span><h1>${t('Một nét lụa.','A touch of silk.')}<br/><em>${t('Một khí chất.','A quiet presence.')}</em></h1><p>${t('Dành cho người phụ nữ yêu vẻ đẹp tinh giản. Tự do trong phong cách, thanh lịch theo cách riêng.','For women drawn to understated beauty. Free in spirit, elegant in their own way.')}</p><a className="solid" href="#collection">${t('KHÁM PHÁ BỘ SƯU TẬP','EXPLORE THE COLLECTION')} <span>↗</span></a><span className="eyebrow" style=${{marginTop:45,fontSize:8,color:'#818573'}}>HƯƠNG VÂN SA · THE ART OF DRESSING</span></div><div className="heroimage"><video src="assets/home-fashion.mp4" autoPlay muted loop playsInline controls preload="metadata" aria-label=${t('Video thời trang Trung Béo Luxury','Trung Beo Luxury fashion video')}></video><span className="caption">01 / ${t('VẺ ĐẸP CỦA SỰ TỐI GIẢN','THE BEAUTY OF SIMPLICITY')}</span></div></section><div className="imageNote">${t('Video đầu trang do shop cung cấp · Các ảnh thời trang khác là ảnh minh họa từ Unsplash','Hero video supplied by the shop · Other fashion images are illustrations from Unsplash')}</div><div className="strip"><span>01 — ${t('TINH GIẢN TRONG ĐƯỜNG NÉT','MINIMAL IN FORM')}</span><span>02 — ${t('TỰ DO TRONG PHONG CÁCH','FREE IN SPIRIT')}</span><span>03 — ${t('THANH LỊCH MỖI NGÀY','EVERYDAY ELEGANCE')}</span></div><section className="section" id="collection"><div className="sectionhead"><div><span className="eyebrow">THE CONSIDERED WARDROBE</span><h2>${t('Chọn nét riêng của bạn','Find your signature')}</h2></div><a className="textlink" href="#style">${t('GỢI Ý PHỐI ĐỒ','STYLE INSPIRATION')} ↗</a></div><div className="filters">${[['all','Tất cả','All styles'],['dress','Đầm','Dresses'],['top','Áo','Tops'],['set','Bộ phối','Sets']].map(f=>html`<button className=${filter===f[0]?'active':''} aria-pressed=${filter===f[0]} onClick=${()=>F(f[0])}>${f[lang+1]}</button>`)}</div><div className="products">${products.filter(p=>filter==='all'||p.type===filter).map(card)}</div></section><section className="editorial" id="story"><div className="editorialimage"><img src="assets/brand.jpg" alt="Nhận diện Trung Béo Luxury" loading="lazy"/></div><div className="editorialcopy"><span className="eyebrow">A NOTE FROM TRUNG BÉO</span><h2>${t('Thanh lịch,\ntheo cách của bạn.','Elegance,\non your terms.')}</h2><p>${t('Một tủ đồ có thể đi cùng bạn qua nhiều nhịp sống: nhẹ nhàng khi dạo phố, chỉn chu ở buổi hẹn, nổi bật vừa đủ trong một tối đặc biệt.','A wardrobe for every rhythm of your life: relaxed on a city walk, composed at a meeting, quietly expressive on a special evening.')}</p><p>${t('Hương Vân Sa là dòng chất liệu thương hiệu định hướng tuyển chọn. Thông tin về thành phần và nguồn gốc của từng sản phẩm sẽ được công bố khi có tài liệu xác minh.','Huong Van Sa is the material direction for the planned collection. Composition and origin will be published for each product once verified documentation is available.')}</p><a href="#contact" className="textlink">${t('KẾT NỐI VỚI THƯƠNG HIỆU','CONNECT WITH THE BRAND')} ↗</a></div></section><section className="section" id="style"><div className="sectionhead"><div><span className="eyebrow">WAYS TO WEAR</span><h2>${t('Từ ngày thường đến dịp đặc biệt','From everyday to occasion')}</h2></div></div><div className="moods"><a href="#collection" className="mood" onClick=${()=>F('top')}><img src=${images[3]} alt="Cảm hứng phong cách thường ngày" loading="lazy"/><div><span className="eyebrow">01 / EVERYDAY POETRY</span><h3>${t('Nhẹ nhàng xuống phố','An effortless day')}</h3><span className="textlink">${t('KHÁM PHÁ PHONG CÁCH','EXPLORE THE STYLE')} ↗</span></div></a><a href="#collection" className="mood" onClick=${()=>F('dress')}><img src=${images[1]} alt="Cảm hứng trang phục dịp đặc biệt" loading="lazy"/><div><span className="eyebrow">02 / AN EVENING TO REMEMBER</span><h3>${t('Một chút kiêu sa','A little radiance')}</h3><span className="textlink">${t('KHÁM PHÁ PHONG CÁCH','EXPLORE THE STYLE')} ↗</span></div></a></div></section><section className="section shop-policies" id="policies"><span className="eyebrow">TRUNG BÉO LUXURY</span><h2>${t('Bảo chứng niềm tin trên từng lựa chọn','Trust in every choice')}</h2><${Policies} lang=${lang}/></section><section className="invitation" id="contact"><span className="eyebrow">YOUR PERSONAL SILK EDIT</span><h2>${t('Tìm một thiết kế dành cho mình.','Find a style that feels like you.')}</h2><p>${t('Tư vấn tại Hà Nội · Giao hàng toàn Việt Nam · Giá niêm yết bằng VNĐ.','Based in Hanoi · Delivery across Vietnam · Prices in VND.')}</p><${Contact} lang=${lang}/></section></main>`}
<footer><div className="footergrid"><div><div className="footerbrand">Trung Béo Luxury</div><p>${t('Một nét lụa. Một khí chất.\nKhông gian thời trang dành cho phong cách riêng của bạn.','A touch of silk. A quiet presence.\nA space for your personal style.')}</p></div><div><h4>${t('KHÁM PHÁ','EXPLORE')}</h4><a href="#collection" onClick=${()=>home('collection')}>${t('Bộ sưu tập','Collection')}</a><a href="#story" onClick=${()=>home('story')}>${t('Câu chuyện thương hiệu','Our story')}</a><a href="#style" onClick=${()=>home('style')}>${t('Cảm hứng phối đồ','Style inspiration')}</a></div><div><h4>${t('CHĂM SÓC KHÁCH HÀNG','CUSTOMER CARE')}</h4><a href="#contact" onClick=${e=>{e.preventDefault();Q('contact')}}>${t('Liên hệ & tư vấn','Contact & styling')}</a><a href="#policies" onClick=${e=>{e.preventDefault();Q('policy')}}>${t('Giao hàng & đổi trả','Delivery & returns')}</a><a href="#privacy" onClick=${e=>{e.preventDefault();Q('privacy')}}>${t('Quyền riêng tư','Privacy')}</a></div></div><div className="footline"><span>© 2026 TRUNG BÉO LUXURY</span><span>${t('HÀ NỘI · TOÀN VIỆT NAM · VNĐ','DESIGN PREVIEW · SALES NOT YET OPEN')}</span></div></footer>
${panel&&html`<div className="overlay" onClick=${()=>Q(null)}><section className="drawer" role="dialog" aria-modal="true" aria-label=${panel} onClick=${e=>e.stopPropagation()} onKeyDown=${e=>{if(e.key==='Escape')Q(null)}}><button className="close" autoFocus onClick=${()=>Q(null)} aria-label="Đóng / Close">×</button>${panel==='menu'?html`<h2>Menu</h2><div className="mobilelinks">${['collection','story','style','contact'].map((a,i)=>html`<a href=${'#'+a} onClick=${()=>home(a)}>${[['Bộ sưu tập','Collection'],['Hương Vân Sa','Huong Van Sa'],['Cảm hứng','Inspiration'],['Liên hệ','Contact']][i][lang]}</a>`)}</div>`:panel==='cart'?html`<h2>${t('Mẫu bạn yêu thích','Your saved styles')} (${cart.length})</h2>${cart.length?cart.map(c=>{const p=products.find(x=>x.id===c.id);return p&&html`<div className="cartitem"><img src=${p.image} alt="Ảnh minh họa"/><div><h3>${p.name[lang]}</h3><p>${t('Cỡ tham khảo','Reference size')}: ${c.size}</p><span>${t('Giá VNĐ: chờ cập nhật','Price not listed')}</span><button onClick=${()=>save(cart.filter(x=>x.key!==c.key))}>${t('Xóa','Remove')}</button></div></div>`}):html`<p className="empty">${t('Túi đồ đang trống. Hãy chọn một mẫu bạn yêu thích.','Your bag is empty. Explore a style you love.')}</p>`}<div className="notice">${t('Đây là túi đồ mẫu, được lưu trên trình duyệt của bạn. Chưa tạo đơn hàng và chưa có thanh toán.','This sample bag is saved in your browser. It does not create an order or process payment.')}</div><button className="solid full" onClick=${()=>{home('collection')}}>${t('TIẾP TỤC KHÁM PHÁ','CONTINUE EXPLORING')} →</button>`:panel==='search'?html`<h2>${t('Tìm thiết kế','Find a style')}</h2><input className="searchinput" value=${query} onChange=${e=>U(e.target.value)} placeholder=${t('Tìm theo tên mẫu…','Search a style name…')} aria-label="Tìm kiếm sản phẩm"/>${products.filter(p=>p.name[lang].toLowerCase().includes(query.toLowerCase())).map(p=>html`<button className="searchresult" onClick=${()=>open(p)}>${p.name[lang]} ↗</button>`)}${!products.some(p=>p.name[lang].toLowerCase().includes(query.toLowerCase()))&&html`<p>${t('Chưa tìm thấy mẫu phù hợp.','No matching styles.')}</p>`}`:panel==='privacy'?html`<h2>${t('Quyền riêng tư','Privacy')}</h2><p>${t('Bản mẫu không yêu cầu tên, địa chỉ, số điện thoại hoặc thông tin thanh toán. Túi đồ được lưu cục bộ trên trình duyệt. Ảnh và phông chữ được tải từ dịch vụ bên ngoài (Unsplash, Google Fonts); mã giao diện sử dụng esm.sh.','This preview does not request your name, address, phone or payment information. Your sample bag is stored locally in this browser. Images and fonts load from Unsplash and Google Fonts; interface code uses esm.sh.')}</p><button className="textlink" onClick=${()=>save([])}>${t('Xóa túi đồ đã lưu','Clear saved bag')}</button>`:panel==='policy'?html`<h2>${t('Quy định mua hàng','Shop policies')}</h2><${Policies} lang=${lang}/>`:html`<h2>${t('Tư vấn & đặt hàng','Contact & orders')}</h2><${Contact} lang=${lang}/>`}</section></div>`}</div>`}
createRoot(document.getElementById('root')).render(html`<${App}/>`);
